import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

calc_vals = vals["Calc"]
calc_out = wb["Calc"]

item = calc_vals["A10"].value

def normalize(value):
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    return str(value).strip()

target = normalize(item)
supplier = None

for sheet_name in ["Supplier_1", "Supplier_2", "Supplier_3"]:
    sheet = vals[sheet_name]
    for row in sheet.iter_rows(min_row=2, min_col=1, max_col=1):
        cell_value = row[0].value
        if cell_value is None:
            continue
        if normalize(cell_value) == target:
            supplier = sheet_name
            break
    if supplier is not None:
        break

calc_out["B7"] = supplier if supplier is not None else None

wb.save(OUT)

print("item:", target)
print("supplier:", supplier)
